var i=[{title:`Wybierz powtarzalny pomiar`,text:`Dobre opcje to dystans, który przechodzisz w ustalonym czasie, czas pokonania znanej trasy, to, czy kończysz zaplanowany trening interwałowy, lub tętno przy wygodnym stałym tempie. RPE sesji uzupełnia te liczby, zwłaszcza jeśli nie masz pulsometru.`},{title:`Utrzymuj podobne warunki testu`,text:`Temperatura, wzniesienia, sen, kofeina, sprzęt i regeneracja wpływają na wyniki. Gdy możesz, porównuj to samo ustawienie bieżni, opór roweru lub trasę na zewnątrz. Niższe tętno nie zawsze oznacza, że jesteś sprawniejszy, bo leki i błąd pomiaru mogą też zmieniać odczyt.`},{title:`Przykład`,text:`Początkujący zaczyna od naprzemiennego marszu przez dwie minuty i łagodnego truchtu przez minutę. Kilka tygodni później kończy więcej interwałów truchtu przy podobnym wysiłku. Ktoś inny jeździ tą samą trasą rowerową i wydaje mu się łatwiejsza, mimo że średnia prędkość pozostaje taka sama.`},{title:`Jak często testować`,text:`Zaplanowana kontrola co kilka tygodni pokazuje trendy, podczas gdy normalne treningi pozostają skupione na ćwiczeniu. Nagły spadek wyników może wynikać ze zmęczenia lub choroby i nie musi oznaczać, że na stałe straciłeś kondycję.`},{title:`Korzystanie z TrainUp`,text:`Po każdym treningu oceniasz wysiłek od 1 do 10, a Historia pokazuje średni wysiłek i wykres z 4 tygodni. Patrz na trend w ciągu tygodni. Pojedyncza liczba tętna lub prędkości nie może zdiagnozować zdrowia układu krążenia ani go zagwarantować.`}];var n=[{label:`NHS: spacerowanie dla zdrowia`,url:`https://www.nhs.uk/live-well/exercise/walking-for-health/`},{label:`Stanowisko ACSM z 2026 roku`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var o={sections:i,sources:n};export{o as default,i as sections,n as sources};